content.query:
let dedicatedLlm = ApiManagementGatewayLlmLog
| where isnotempty(DeploymentName)
| project CorrelationId, PromptTokens=toreal(PromptTokens), CompletionTokens=toreal(CompletionTokens);
let legacyLlm = AzureDiagnostics
| where Category == 'GatewayLlmLogs'
| where isnotempty(deploymentName_s) and totalTokens_d > 0
| project CorrelationId, PromptTokens=toreal(promptTokens_d), CompletionTokens=toreal(completionTokens_d);
let llmLogs = union isfuzzy=true dedicatedLlm, legacyLlm;
let dedicatedGateway = ApiManagementGatewayLogs
| summarize SubscriptionName=take_any(ApimSubscriptionId) by CorrelationId;
let legacyGateway = AzureDiagnostics
| where Category == 'GatewayLogs'
| summarize SubscriptionName=take_any(apimSubscriptionId_s) by CorrelationId;
let gatewayLogs = union isfuzzy=true dedicatedGateway, legacyGateway | summarize SubscriptionName=take_any(SubscriptionName) by CorrelationId;
llmLogs
| join kind=leftouter gatewayLogs on CorrelationId
| summarize PromptTokens = sum(PromptTokens), CompletionTokens = sum(CompletionTokens)
    by Department = replace_string(SubscriptionName, 'subscription-', '')
| order by PromptTokens desc

let dedicatedGateway = ApiManagementGatewayLogs | where isnotempty(BackendId) | project Backend=BackendId;
let legacyGateway = AzureDiagnostics | where Category == 'GatewayLogs' and isnotempty(backendId_s) | project Backend=backendId_s;
union isfuzzy=true dedicatedGateway, legacyGateway
| summarize Requests=count() by Backend
| order by Requests desc

let dedicatedGateway = ApiManagementGatewayLogs | project StatusCode=tostring(ResponseCode);
let legacyGateway = AzureDiagnostics | where Category == 'GatewayLogs' | project StatusCode=tostring(toint(responseCode_d));
union isfuzzy=true dedicatedGateway, legacyGateway
| summarize Requests=count() by StatusCode
| order by StatusCode asc
